const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function richHtml(value=''){const doc=new DOMParser().parseFromString(String(value),'text/html');doc.querySelectorAll('script,style,iframe,object,embed').forEach(n=>n.remove());doc.body.querySelectorAll('*').forEach(n=>{[...n.attributes].forEach(a=>{if(a.name!=='href')n.removeAttribute(a.name)});if(n.tagName==='A'){const href=n.getAttribute('href')||'';if(!/^(https?:|mailto:|#)/i.test(href))n.removeAttribute('href')}else if(!['P','BR','B','STRONG','I','EM','U','UL','OL','LI','H2','H3','BLOCKQUOTE','A'].includes(n.tagName)){n.replaceWith(...n.childNodes)}});return doc.body.innerHTML}
const client=window.supabase?.createClient(window.WOODRI_SUPABASE_URL,window.WOODRI_SUPABASE_KEY);
const toggle=$('.menu-toggle'),nav=$('.nav-links'); toggle?.addEventListener('click',()=>nav?.classList.toggle('open'));
