async function rows(table, published=true){if(!client)return [];let q=client.from(table).select('*');if(published&&table!=='vouchers')q=q.eq('is_published',true);const {data,error}=await q.order('created_at',{ascending:false});if(error){console.error(error);return []}return data||[]}
async function setting(key){if(!client)return null;const {data}=await client.from('site_settings').select('value').eq('key',key).maybeSingle();return data?.value||null}
function setNotice(form,msg){const box=$('.success',form);if(box){box.style.display='block';box.textContent=msg}}
let activeDraftPreview=null,queuedPublicPreview=null,publicPreviewReady=false;
function markPreviewSaved(message='Perubahan sudah tersimpan di website.') { activeDraftPreview=null; const label=$('#preview-state'); if(label)label.textContent=message; $('#site-preview-frame')?.contentWindow?.location.reload() }
function sendPreviewDraft(){if(!activeDraftPreview)return;[$('#site-preview-frame'),$('#layout-live-frame')].forEach(frame=>{try{frame?.contentWindow?.postMessage({type:'woodri-preview-draft',draft:activeDraftPreview},location.origin)}catch(_){}})}
function publicProductCard(value,id='draft'){return `<article class="catalog-card preview-draft" data-product-id="${esc(id)}"><img src="${esc(value.image||'souvenircostum.avif')}" alt="${esc(value.name||'Pratinjau produk Woodri')}"><div><small>${esc(value.category||'Produk Woodri')}</small><h3>${esc(value.name||'Nama produk')}</h3><p>${esc(value.description||'Deskripsi produk yang Anda tulis akan tampil di sini.')}</p><a href="kontak/">Tanyakan opsi custom ↗</a><details><summary>Detail bahan & spesifikasi</summary><div class="spec-list"><b>Bahan</b><span>${esc(value.materials||'—')}</span><b>Spesifikasi</b><span>${esc(value.specs||'—')}</span></div></details></div></article>`}
function applyPublicDraft(draft){if(!draft)return;const {kind,value,id}=draft;const isDraft=id||'draft';if(kind==='layout'){applyHomeLayout(value);return}if(kind==='home-banner'){renderHomeBanner({...value,active:value.active!==false});return}if(kind==='slide'){clearInterval(heroTimer);const hero=$('#hero-slider');if(hero){const img=$('.hero-slide-image',hero);if(img&&value.image)img.src=value.image;const title=$('[data-copy="headline"]'),desc=$('[data-copy="description"]');if(title)title.textContent=value.title||'Judul promosi';if(desc)desc.textContent=value.subtitle||'';const cap=$('.slide-caption',hero);if(cap)cap.textContent=value.subtitle||'Pratinjau banner';const cta=$('.hero-actions .button');if(cta){cta.textContent=(value.cta||'Jelajahi koleksi')+' ↗';cta.href=value.link||'katalog/'}}return}if(kind==='home-banner')return;if(kind==='copy'){for(const key of ['headline','subheadline','description']){const el=$(`[data-copy="${key}"]`);if(el&&value[key])el.textContent=value[key]}return}if(kind==='promo'){const el=$('.announcement');if(el&&value.banner)el.textContent=`${value.banner} ✳ ${value.cta||''}`;return}if(kind==='product'){const grid=$('.catalog-grid');if(grid&&location.pathname.includes('/katalog')){let card=$(`[data-product-id="${CSS.escape(isDraft)}"]`,grid);if(!card){card=document.createElement('div');card.dataset.productId=isDraft;grid.prepend(card)}card.outerHTML=publicProductCard(value,isDraft)}const home=$('#home-products');if(home){let card=$(`[data-preview-product="${CSS.escape(isDraft)}"]`,home);if(!card){card=document.createElement('a');card.className='product-card preview-draft';card.dataset.previewProduct=isDraft;home.prepend(card)}card.outerHTML=`<a class="product-card preview-draft" data-preview-product="${esc(isDraft)}" href="katalog/"><div class="product-image"><img src="${esc(value.image||'souvenircostum.avif')}" alt="${esc(value.name||'Produk Woodri')}"><span>PREVIEW</span></div><div class="product-info"><div><h3>${esc(value.name||'Nama produk')}</h3><p>${esc(value.description||'Deskripsi produk')}</p></div><b>↗</b></div></a>`}return}if(kind==='post'){const grid=$('#blog-posts');if(grid){let card=$(`[data-post-preview="${CSS.escape(isDraft)}"]`,grid)||$(`[data-post-id="${CSS.escape(isDraft)}"]`,grid);if(!card){card=document.createElement('article');card.dataset.postPreview=isDraft;grid.prepend(card)}card.outerHTML=`<article class="journal-card preview-draft" data-post-preview="${esc(isDraft)}">${value.image?`<img src="${esc(value.image)}" alt="${esc(value.title||'Artikel Woodri')}">`:''}<div><small>${esc(value.category||'Jurnal Woodri')}</small><h3>${esc(value.title||'Judul artikel')}</h3><p>${esc(value.excerpt||'Ringkasan artikel')}</p><details open><summary>Pratinjau isi</summary><p>${esc(value.content||'Isi artikel')}</p></details></div></article>`}return}if(kind==='story'){const grid=$('#testimonials');if(grid){let card=$(`[data-story-preview="${CSS.escape(isDraft)}"]`,grid)||$(`[data-story-id="${CSS.escape(isDraft)}"]`,grid);if(!card){card=document.createElement('article');card.dataset.storyPreview=isDraft;grid.prepend(card)}card.outerHTML=`<article class="story-card preview-draft" data-story-preview="${esc(isDraft)}"><div class="org-logo">${value.logo?`<img src="${esc(value.logo)}" alt="Logo ${esc(value.name||'Klien')}" style="max-width:110px;max-height:40px;object-fit:contain">`:esc(value.name||'Nama klien')}</div><blockquote>“${esc(value.quote||'Teks testimoni')}”</blockquote><small>${esc(value.name||'Nama organisasi')}</small></article>`}return}if(kind==='logo'){const grid=$('#client-logos');if(grid){const old=$('[data-logo-preview]',grid)||$(`[data-partner-id="${CSS.escape(isDraft)}"]`,grid);old?.remove();const node=document.createElement('b');node.className='managed-logo preview-draft';node.dataset.logoPreview='true';node.innerHTML=`${value.logo?`<img src="${esc(value.logo)}" alt="Logo ${esc(value.name||'Mitra')}">`:''}${esc(value.name||'Nama mitra')}`;grid.prepend(node)}}}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='woodri-preview-draft')return;if(publicPreviewReady)applyPublicDraft(event.data.draft);else queuedPublicPreview=event.data.draft});
function adminPreviewKind(form){return ({'home-banner-form':'home-banner','slide-form':'slide','product-form':'product','story-form':'story','logo-form':'logo','blog-form':'post','copy-form':'copy','promo-form':'promo','layout-editor-form':'layout'})[form.id]||null}
function previewFormDraft(form){const kind=adminPreviewKind(form);if(!kind)return;if(form.id==='layout-editor-form'){activeDraftPreview={kind:'layout',value:collectLayoutDraft()};const label=$('#preview-state');if(label)label.textContent='Pratinjau layout · perubahan belum disimpan';sendPreviewDraft();return}const targets={product:'katalog/',post:'blog/',story:'testimoni/','home-banner':'home/',slide:'home/',promo:'home/',copy:'home/',logo:'home/'};const picker=$('#preview-page'),frame=$('#site-preview-frame');if(picker&&targets[kind]&&picker.value!==targets[kind]){picker.value=targets[kind];if(frame)frame.src=targets[kind]}const value=Object.fromEntries([...new FormData(form)].filter(([key,val])=>!(val instanceof File)));if(form.elements.active)value.active=form.elements.active.checked;activeDraftPreview={kind,value,id:form.dataset.editId||null};const label=$('#preview-state');if(label)label.textContent='Pratinjau draf · belum disimpan';sendPreviewDraft()}
function bindAdminPreview(){const dialog=$('#site-preview-dialog'),frame=$('#site-preview-frame'),page=$('#preview-page');if(!dialog||!frame)return;$('#preview-open')?.addEventListener('click',()=>{if(!dialog.open)dialog.showModal();setTimeout(sendPreviewDraft,200)});$('#preview-close')?.addEventListener('click',()=>dialog.close());$('#preview-refresh')?.addEventListener('click',()=>{activeDraftPreview=null;frame.contentWindow.location.reload();const label=$('#preview-state');if(label)label.textContent='Menampilkan perubahan yang sudah tersimpan.'});page?.addEventListener('change',()=>{frame.src=page.value});frame.addEventListener('load',sendPreviewDraft);document.addEventListener('input',e=>{const form=e.target.closest('form');if(form)previewFormDraft(form)});document.addEventListener('change',e=>{const form=e.target.closest('form');if(form&&!e.target.matches('[type=file]'))previewFormDraft(form)});document.addEventListener('click',async e=>{const cancel=e.target.closest('[data-cancel-form]');if(cancel){const form=cancel.closest('form');if(!form)return;form.reset();delete form.dataset.editId;const button=$('button[type="submit"]',form);if(button?.dataset.originalText){button.innerHTML=button.dataset.originalText;delete button.dataset.originalText}$$('.upload-preview',form).forEach(img=>{img.hidden=true;img.removeAttribute('src')});activeDraftPreview=null;frame.contentWindow.location.reload();const label=$('#preview-state');if(label)label.textContent='Draf dibatalkan; menampilkan versi yang tersimpan.';return}const reset=e.target.closest('[data-reset-setting]');if(reset){if(!confirm('Hapus perubahan tersimpan dan kembalikan bagian ini ke tampilan awal?'))return;const key=reset.dataset.resetSetting;if(key==='home_banner'){const value={title:'',subtitle:'',image:'',cta:'',link:'',active:false};const {error}=await client.from('site_settings').upsert({key,value,updated_at:new Date().toISOString()});if(error)return alert('Banner gagal dihapus.');renderHomeBanner(value)}else{const {error}=await client.from('site_settings').delete().eq('key',key);if(error)return alert('Perubahan gagal dihapus.')}reset.closest('form')?.reset();$$('.upload-preview',reset.closest('form'))?.forEach(img=>{img.hidden=true;img.removeAttribute('src')});await renderAdmin();markPreviewSaved('Perubahan dihapus; menampilkan tampilan awal.')}})}

async function renderPublic(){if(!client){renderInstagramFeed();publicPreviewReady=true;if(queuedPublicPreview){applyPublicDraft(queuedPublicPreview);queuedPublicPreview=null}return}
  const [products,stories,logos,posts,promo,copy,vouchers,slides,homeBanner,instagramLinks,layoutConfig]=await Promise.all([rows('products'),rows('testimonials'),rows('partners'),rows('posts'),setting('promo'),setting('copy'),rows('vouchers'),rows('hero_slides'),setting('home_banner'),setting('instagram_links'),setting('home_layout')]);
  const homeProducts=$('#home-products');if(homeProducts)homeProducts.innerHTML=products.slice(0,3).map((p,i)=>`<a class="product-card" data-preview-product="${esc(p.id)}" href="katalog/"><div class="product-image">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:'<div class="product-placeholder">WOODRI · CUSTOM</div>'}<span>${String(i+1).padStart(2,'0')}</span></div><div class="product-info"><div><h3>${esc(p.name)}</h3><p>${richHtml(p.description||p.category||'Hadiah custom dari Woodri')}</p></div><b>↗</b></div></a>`).join('')||'<p class="public-empty">Koleksi pilihan Woodri akan segera hadir.</p>';
  const logoArea=$('#client-logos');if(logoArea&&logos.length)logoArea.innerHTML=logos.map(x=>`<b class="managed-logo" data-partner-id="${esc(x.id)}">${x.logo?`<img src="${esc(x.logo)}" alt="Logo ${esc(x.name)}">`:''}${esc(x.name)}</b>`).join('');
  if(copy){for(const [key,selector] of Object.entries({headline:'[data-copy="headline"]',description:'[data-copy="description"]',subheadline:'[data-copy="subheadline"]'})){const el=$(selector);if(el&&copy[key])el.innerHTML=key==='description'?richHtml(copy[key]):esc(copy[key])}}
  const tb=$('#testimonials');if(tb)tb.innerHTML=stories.map(x=>`<article class="story-card" data-story-id="${esc(x.id)}"><div class="org-logo">${x.logo?`<img src="${esc(x.logo)}" alt="Logo ${esc(x.name)}" style="max-width:110px;max-height:40px;object-fit:contain">`:esc(x.name)}</div><blockquote>${richHtml(x.quote)}</blockquote><small>${esc(x.name)}</small></article>`).join('')||'<p class="public-empty">Cerita kolaborasi akan segera hadir.</p>';
  const bp=$('#blog-posts');if(bp)bp.innerHTML=posts.map(x=>`<article class="journal-card" data-post-id="${esc(x.id)}">${x.image?`<img src="${esc(x.image)}" alt="${esc(x.title)}">`:''}<div><small>${esc(x.category||'Woodri Journal')}</small><h3>${esc(x.title)}</h3><p>${richHtml(x.excerpt||'')}</p>${x.content?`<details><summary>Baca artikel</summary><div class="rich-content">${richHtml(x.content)}</div></details>`:''}</div></article>`).join('')||'<p class="public-empty">Artikel terbaru akan segera hadir.</p>';
  const cg=$('.catalog-grid');if(cg&&location.pathname.includes('/katalog')){$$('.catalog-card',cg).forEach(x=>x.remove());for(const p of products){const c=document.createElement('article');c.className='catalog-card';c.dataset.category=(p.category||'custom').toLowerCase();c.dataset.managed='true';c.dataset.productId=p.id;c.innerHTML=`${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:'<div class="product-placeholder">WOODRI · CUSTOM</div>'}<div><small>${esc(p.category)}</small><h3>${esc(p.name)}</h3><div class="rich-content">${richHtml(p.description||'Produk dapat disesuaikan berdasarkan kebutuhan proyek.')}</div><a href="kontak/">Tanyakan opsi custom ↗</a><details><summary>Detail bahan & spesifikasi</summary><div class="spec-list"><b>Bahan</b><span>${esc(p.materials||'Konsultasikan')}</span><b>Spesifikasi</b><span>${esc(p.specs||'Custom sesuai brief')}</span></div></details></div>`;cg.append(c)}if(!products.length)cg.innerHTML='<p class="public-empty">Katalog sedang diperbarui. Silakan hubungi Woodri untuk konsultasi.</p>'}
  const announcement=$('.announcement');if(announcement&&promo?.banner)announcement.innerHTML=`${esc(promo.banner)} <span>✳</span> <a href="wizard/">${esc(promo.cta||'Rencanakan hadiah')} ↗</a>`;
  renderHomeBanner(homeBanner);
  renderInstagramFeed(instagramLinks);
  if(slides.length) setupHeroSlider(slides);
  applyHomeLayout(layoutConfig);
  const voucher=vouchers.find(v=>v.is_active);window.WOODRI_ACTIVE_VOUCHER=voucher||null;publicPreviewReady=true;if(queuedPublicPreview){applyPublicDraft(queuedPublicPreview);queuedPublicPreview=null}
}
async function renderInstagramFeed(config){const root=$('#instagram-grid');if(!root)return;const profile='https://www.instagram.com/woodri.id/';const links=(config?.items||[]).map(item=>validInstagramPostLink(item.link)).filter(Boolean).slice(0,3);if(links.length){root.innerHTML=links.map((link,i)=>`<a class="instagram-placeholder instagram-post-link" href="${esc(link)}" target="_blank" rel="noopener"><span>◎</span><b>Posting terbaru ${i===0?'Woodri':`Woodri ${i+1}`}</b><small>@woodri.id · Lihat di Instagram ↗</small></a>`).join('');return}root.innerHTML='<div class="instagram-feed-status">Memuat posting terbaru dari @woodri.id…</div>';if(!client){root.innerHTML=`<a class="instagram-placeholder" href="${profile}" target="_blank" rel="noopener"><span>◎</span><b>Buka Instagram Woodri</b><small>@woodri.id</small></a>`;return}try{const response=await fetch(`${window.WOODRI_SUPABASE_URL}/functions/v1/instagram-feed`,{method:'GET',mode:'cors',credentials:'omit',cache:'no-store'});if(!response.ok)throw new Error(`Feed belum tersedia (${response.status})`);const data=await response.json(),items=Array.isArray(data?.items)?data.items:[];if(!items.length)throw new Error('Feed Instagram belum tersedia');root.innerHTML=items.slice(0,3).map((item,i)=>{const image=item.media_type==='VIDEO'?item.thumbnail_url:item.media_url;const caption=item.caption||`Posting Instagram Woodri ${i+1}`;if(!image)return '';return `<a class="instagram-card" href="${esc(validInstagramPostLink(item.permalink)||profile)}" target="_blank" rel="noopener"><img src="${esc(image)}" alt="${esc(caption)}" loading="lazy"><span>◎</span><b>${esc(caption)}<small>${item.timestamp?new Date(item.timestamp).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'@woodri.id'}</small></b></a>`}).join('')||`<a class="instagram-placeholder" href="${profile}" target="_blank" rel="noopener"><span>◎</span><b>Lihat posting terbaru Woodri</b><small>@woodri.id · Buka Instagram</small></a>`}catch(_){root.innerHTML=`<a class="instagram-placeholder" href="${profile}" target="_blank" rel="noopener"><span>◎</span><b>Lihat posting terbaru Woodri</b><small>@woodri.id · Buka Instagram</small></a>`}}
function bindSocialLinks(){if(admin)return;document.querySelectorAll('footer').forEach(footer=>{if($('[data-social-links]',footer))return;const links=document.createElement('div');links.className='social-links';links.dataset.socialLinks='true';links.innerHTML='<a href="https://www.instagram.com/woodri.id/" target="_blank" rel="noopener">Instagram <span>@woodri.id ↗</span></a><a href="https://wa.me/6289647188725" target="_blank" rel="noopener">WhatsApp <span>089647188725 ↗</span></a>';footer.append(links)});if(!$('[data-whatsapp-float]')){const link=document.createElement('a');link.href='https://wa.me/6289647188725';link.target='_blank';link.rel='noopener';link.className='whatsapp-float';link.dataset.whatsappFloat='true';link.setAttribute('aria-label','Hubungi Woodri melalui WhatsApp');link.innerHTML='<span>☏</span> Chat WhatsApp';document.body.append(link)}}
function renderHomeBanner(value){const el=$('#home-promo-banner');if(!el)return;const banner=value||{title:'Hadiah yang membawa cerita.',subtitle:'Rancang hadiah custom untuk momen yang layak diingat.',image:'souvenircostum.avif',cta:'Jelajahi koleksi',link:'katalog/',active:true};if(banner.active===false){el.hidden=true;return}el.hidden=false;const image=$('.home-promo-image',el);if(image&&banner.image){image.src=banner.image;image.alt=banner.title||'Banner promosi Woodri'}const label=$('.section-label',el),title=$('h2',el),desc=$('p',el),cta=$('.home-promo-cta',el);if(title)title.textContent=banner.title||'';if(desc)desc.textContent=banner.subtitle||'';if(cta){cta.href=banner.link||'katalog/';const span=document.createElement('span');span.textContent='↗';cta.textContent=banner.cta||'Jelajahi koleksi';cta.append(' ',span)}}
const HOME_LAYOUT_DEFAULT=['home-banner','hero','trust','intro','collection','statement','services','mini-links','contact-band'];
const HOME_LAYOUT_LABELS={'home-banner':'Banner beranda',hero:'Hero utama',trust:'Logo mitra',intro:'Tentang Woodri',collection:'Katalog pilihan',statement:'Pernyataan brand',services:'Layanan', 'mini-links':'Tautan inspirasi','contact-band':'Ajakan kontak'};
let layoutDraft={order:[...HOME_LAYOUT_DEFAULT],overrides:{},blocks:[]},layoutEditorReady=false,layoutFrameReady=false;
const safeHref=v=>/^(https?:\/\/|mailto:|tel:|\/|#|[\w.-]+\/)/i.test(String(v||''))?String(v):'#';
function validInstagramPostLink(value){try{const url=new URL(String(value||''));return url.protocol==='https:'&&['instagram.com','www.instagram.com'].includes(url.hostname)&&/^\/(p|reel|tv)\/[A-Za-z0-9_-]+\/?$/.test(url.pathname)?url.href:''}catch(_){return ''}}
function applyHomeLayout(config){
  const main=$('body:not(.admin-body) main');if(!main||!config)return;
  const order=(Array.isArray(config.order)?config.order:HOME_LAYOUT_DEFAULT).filter(key=>key!=='instagram'),overrides=config.overrides||{},blocks=config.blocks||[];
  $$(':scope > [data-layout-key]',main).forEach(section=>{const v=overrides[section.dataset.layoutKey];if(!v)return;const title=$('h1,h2,h3',section),paragraph=$('p',section),image=$('img',section),button=$('a.button, a.text-link, a.home-promo-cta',section);if(v.title&&title)title.innerHTML=richHtml(v.title);if(v.text&&paragraph)paragraph.innerHTML=richHtml(v.text);if(v.image&&image){image.src=v.image;image.alt=v.title||image.alt}if(v.button&&button)button.textContent=v.button;if(v.link&&button)button.href=safeHref(v.link)});
  const oldCustom=new Map($$('.layout-custom-section[data-custom-layout]',main).map(n=>[n.dataset.customLayout,n])),allCustom=new Map();
  for(const block of blocks){let section=oldCustom.get(String(block.id));if(!section){section=document.createElement('section');section.className='layout-custom-section section';section.dataset.customLayout=block.id;main.append(section)}oldCustom.delete(String(block.id));allCustom.set(String(block.id),section);const markup=`<div class="custom-layout-copy"><span class="section-label">${esc(block.eyebrow||'CERITA WOODRI')}</span><h2>${richHtml(block.title||'')}</h2><div class="rich-content">${richHtml(block.text||'')}</div>${block.button?`<a class="button button-dark" href="${esc(safeHref(block.link))}">${esc(block.button)} <span>↗</span></a>`:''}</div>${block.image?`<img class="custom-layout-image" src="${esc(block.image)}" alt="${esc(block.title||'Foto Woodri')}">`:''}`;if(section.dataset.renderedMarkup!==markup){section.innerHTML=markup;section.dataset.renderedMarkup=markup}}
  oldCustom.forEach(n=>n.remove());
  const built=Object.fromEntries($$(':scope > [data-layout-key]',main).map(n=>[n.dataset.layoutKey,n])),desired=order.map(key=>built[key]||(key.startsWith('custom:')?allCustom.get(key.slice(7)):null)).filter(Boolean);
  if(built.instagram){const collectionIndex=desired.indexOf(built.collection);desired.splice(collectionIndex>=0?collectionIndex+1:desired.length,0,built.instagram)}
  HOME_LAYOUT_DEFAULT.forEach(key=>{if(built[key]&&!desired.includes(built[key]))desired.push(built[key])});blocks.forEach(block=>{const node=allCustom.get(String(block.id));if(node&&!desired.includes(node))desired.push(node)});
  const keyed=new Set(desired),others=[...main.children].filter(n=>!keyed.has(n)),current=[...main.children].filter(n=>keyed.has(n));
  if(current.length!==desired.length||current.some((node,i)=>node!==desired[i])){const fragment=document.createDocumentFragment();desired.forEach(n=>fragment.append(n));others.forEach(n=>fragment.append(n));main.append(fragment)}
}
