function drawList(id,items){const el=$('#'+id);if(!el)return;const table=({'product-list':'products','story-list':'testimonials','logo-list':'partners','blog-list':'posts','slide-list':'hero_slides'})[id];el.innerHTML=items.map(x=>`<div class="admin-item"><span>${table==='products'&&x.image?`<button type="button" class="admin-product-image-edit" data-edit-product-image="${esc(x.id)}" aria-label="Edit foto ${esc(x.name)}"><img src="${esc(x.image)}" alt=""><small>Edit foto</small></button>`:''}<b>${esc(x.name||x.title)}</b> · ${esc(x.category||x.materials||x.quote||x.subtitle||'')}</span><span><button type="button" data-edit-table="${esc(table)}" data-id="${x.id}">Edit</button><button type="button" data-delete="${esc(table)}" data-id="${x.id}">Hapus</button></span></div>`).join('')||'<div class="notice">Belum ada entri.</div>'}
async function renderTeam(){const box=$('#team-list');if(!box||!client)return;const {data,error}=await client.rpc('list_woodri_admins');if(error){box.innerHTML='<div class="notice">Daftar admin belum tersedia. Jalankan SQL terbaru dari supabase/schema.sql.</div>';return}const {data:{user}}=await client.auth.getUser();box.innerHTML=(data||[]).map(row=>`<div class="admin-item team-item"><span><b>${esc(row.email)}</b><small>Admin sejak ${new Date(row.created_at).toLocaleDateString('id-ID')}</small></span>${row.user_id===user?.id?'<span class="current-admin">Akun Anda</span>':`<button data-remove-admin="${esc(row.user_id)}" type="button">Cabut akses</button>`}</div>`).join('')||'<div class="notice">Belum ada admin.</div>';}
async function renderAdmin(){const [leads,products,stories,logos,posts,promo,copy,vouchers,slides,homeBanner,instagramLinks,layoutConfig]=await Promise.all([rows('leads',false),rows('products',false),rows('testimonials',false),rows('partners',false),rows('posts',false),setting('promo'),setting('copy'),rows('vouchers',false),rows('hero_slides',false),setting('home_banner'),setting('instagram_links'),setting('home_layout')]);const date=$('#admin-date');if(date)date.textContent=new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#lead-count').textContent=leads.length;$('#product-count').textContent=products.length;$('#voucher-code').textContent=vouchers.find(v=>v.is_active)?.code||'—';$('#lead-list').innerHTML=leads.map(x=>`<article class="lead-item"><b>${esc(x.name)}</b> · ${esc(x.company)}<small>${esc(x.email)} · ${esc(x.whatsapp)} · ${new Date(x.created_at).toLocaleString('id-ID')}</small>Kebutuhan: ${esc(x.event)} | Material: ${esc(x.material)} | Kuantitas: ${esc(x.quantity)}<br>${esc(x.details)}<button class="lead-delete" data-lead-delete="${x.id}" type="button">Hapus prospek</button></article>`).join('')||'<div class="notice">Belum ada prospek.</div>';drawList('product-list',products);drawList('story-list',stories);drawList('logo-list',logos);drawList('blog-list',posts);drawList('slide-list',slides);const instagramForm=$('#instagram-links-form');if(instagramForm&&instagramLinks)(instagramLinks.items||[]).forEach((item,i)=>{if(instagramForm.elements[`link${i+1}`])instagramForm.elements[`link${i+1}`].value=item.link||''});const pf=$('#promo-form');if(pf&&promo){pf.elements.banner.value=promo.banner||'';pf.elements.cta.value=promo.cta||'';const v=vouchers.find(x=>x.is_active);if(v){pf.elements.code.value=v.code;pf.elements.discount.value=v.discount;pf.elements.expiry.value=v.expires_on||''}}
  const hb=$('#home-banner-form');if(hb){const banner=homeBanner||{title:'Hadiah yang membawa cerita.',subtitle:'Rancang hadiah custom untuk momen yang layak diingat.',image:'souvenircostum.avif',cta:'Jelajahi koleksi',link:'katalog/',active:true};for(const [k,v] of Object.entries(banner))if(hb.elements[k]&&hb.elements[k].type!=='checkbox')hb.elements[k].value=v||'';if(hb.elements.active)hb.elements.active.checked=banner.active!==false;const preview=$('.upload-preview',hb);if(preview&&banner.image){preview.src=banner.image;preview.hidden=false}const current=$('#home-banner-current');if(current)current.innerHTML=`<div class="admin-item"><span><b>Banner homepage saat ini</b><small>${esc(banner.title||'Tanpa judul')} · ${banner.active===false?'Tidak ditampilkan':'Tampil di beranda'}</small></span><button type="button" data-edit-setting="home_banner">Edit banner</button></div>`}
  initLayoutEditor(layoutConfig);const cf=$('#copy-form');if(cf&&copy)for(const [k,v] of Object.entries(copy))if(cf.elements[k])cf.elements[k].value=v;
}
async function saveForm(id,table,transform=v=>v){const f=$('#'+id);if(!f)return;f.addEventListener('submit',async e=>{e.preventDefault();const value=transform(Object.fromEntries(new FormData(f)));const editId=f.dataset.editId;const result=editId?await client.from(table).update(value).eq('id',editId):await client.from(table).insert(value);if(result.error){console.error(result.error);return setNotice(f,'Tidak tersimpan. Periksa data lalu coba lagi.')}delete f.dataset.editId;f.reset();$$('.upload-preview',f).forEach(img=>{img.hidden=true;img.removeAttribute('src')});$$('[data-upload-status]',f).forEach(st=>st.textContent='Pilih foto dari perangkat · maks. 10 MB');const button=$('button[type="submit"]',f);if(button?.dataset.originalText){button.innerHTML=button.dataset.originalText;delete button.dataset.originalText}await renderAdmin();await renderPublic();markPreviewSaved()})}
if(admin){bindImageUploads();bindAdminPreview();initAdmin().then(()=>{if($('#promo-form')){
  saveForm('product-form','products');saveForm('story-form','testimonials');saveForm('logo-form','partners');saveForm('blog-form','posts');saveForm('slide-form','hero_slides');
  $('#promo-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,v=Object.fromEntries(new FormData(f));const {error:se}=await client.from('site_settings').upsert({key:'promo',value:{banner:v.banner,cta:v.cta},updated_at:new Date().toISOString()});if(se)return setNotice(f,'Banner belum tersimpan.');await client.from('vouchers').update({is_active:false}).eq('is_active',true);const {error:ve}=await client.from('vouchers').insert({code:v.code.toUpperCase(),discount:Number(v.discount)||0,expires_on:v.expiry||null,is_active:true});if(ve){console.error(ve);return setNotice(f,'Banner tersimpan, tetapi voucher gagal diperbarui. Pastikan kodenya unik.')}setNotice(f,'Banner dan voucher tersimpan.');await renderAdmin();await renderPublic();markPreviewSaved()});
  $('#home-banner-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,v=Object.fromEntries(new FormData(f));const value={title:v.title,subtitle:v.subtitle,image:v.image,cta:v.cta,link:v.link,active:f.elements.active.checked};const {error}=await client.from('site_settings').upsert({key:'home_banner',value,updated_at:new Date().toISOString()});if(error)return setNotice(f,'Banner belum tersimpan. Jalankan schema terbaru terlebih dahulu.');setNotice(f,'Banner beranda berhasil diperbarui.');renderHomeBanner(value);await renderAdmin();await renderPublic();markPreviewSaved()});
  $('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,v=Object.fromEntries(new FormData(f));if(v.password!==v.confirm)return setNotice(f,'Kedua kata sandi tidak sama.');const {error}=await client.auth.updateUser({password:v.password});if(error)return setNotice(f,'Kata sandi gagal diperbarui. Pastikan minimal 8 karakter.');f.reset();setNotice(f,'Kata sandi berhasil diperbarui.');});
  $('#team-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,v=Object.fromEntries(new FormData(f));setNotice(f,'Membuat akun admin…');const {data,error}=await client.functions.invoke('create-admin-user',{body:{email:v.email,password:v.password}});if(error)return setNotice(f,error.message.includes('Failed to send')?'Layanan pembuatan admin belum aktif. Deploy fungsi Supabase terlebih dahulu.':'Akun admin gagal dibuat. Pastikan fungsi Supabase sudah di-deploy.');f.reset();setNotice(f,`Akun admin ${data.email} berhasil dibuat. Kirim kredensial awal secara aman kepada admin baru.`);await renderTeam()});
  $('#instagram-links-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const items=[1,2,3].map(i=>({link:validInstagramPostLink(form.elements[`link${i}`].value.trim())})).filter(item=>item.link);const {error}=await client.from('site_settings').upsert({key:'instagram_links',value:{items},updated_at:new Date().toISOString()});if(error)return setNotice(form,'Link belum tersimpan. Periksa format link dan coba lagi.');setNotice(form,'Link posting Instagram sudah disimpan.');await renderPublic();markPreviewSaved()});
  $('#copy-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,v=Object.fromEntries(new FormData(f));const {error}=await client.from('site_settings').upsert({key:'copy',value:v,updated_at:new Date().toISOString()});setNotice(f,error?'Teks belum tersimpan.':'Teks website tersimpan.');await renderPublic();markPreviewSaved()});
  document.addEventListener('click',async e=>{const removeAdmin=e.target.closest('[data-remove-admin]');if(removeAdmin){if(!confirm('Cabut akses admin ini? Akun tersebut tidak dapat lagi mengubah website.'))return;const {error}=await client.rpc('revoke_woodri_admin',{target_user_id:removeAdmin.dataset.removeAdmin});if(error)alert(error.message||'Akses admin gagal dicabut.');else await renderTeam();return}const leadDelete=e.target.closest('[data-lead-delete]');if(leadDelete){if(!confirm('Hapus data prospek ini?'))return;const {error}=await client.from('leads').delete().eq('id',leadDelete.dataset.leadDelete);if(error)alert('Prospek gagal dihapus.');else await renderAdmin();return}const settingEdit=e.target.closest('[data-edit-setting]');if(settingEdit){const form=$('#home-banner-form');if(!form)return;const {data,error}=await client.from('site_settings').select('value').eq('key',settingEdit.dataset.editSetting).maybeSingle();if(error)return alert('Banner belum dapat dimuat untuk diedit.');const value=data?.value||{title:'Hadiah yang membawa cerita.',subtitle:'Rancang hadiah custom untuk momen yang layak diingat.',image:'souvenircostum.avif',cta:'Jelajahi koleksi',link:'katalog/',active:true};for(const [key,val] of Object.entries(value))if(form.elements[key]&&form.elements[key].type!=='checkbox')form.elements[key].value=val||'';form.elements.active.checked=value.active!==false;const preview=$('.upload-preview',form);if(preview&&value.image){preview.src=value.image;preview.hidden=false}form.scrollIntoView({behavior:'smooth',block:'center'});previewFormDraft(form);return}const edit=e.target.closest('[data-edit-table]');if(edit){const formId=({'products':'product-form','testimonials':'story-form','partners':'logo-form','posts':'blog-form','hero_slides':'slide-form'})[edit.dataset.editTable],form=$('#'+formId);const {data,error}=await client.from(edit.dataset.editTable).select('*').eq('id',edit.dataset.id).single();if(error||!form)return alert('Data tidak berhasil dibuka untuk diedit.');for(const field of form.elements)if(field.name&&data[field.name]!=null){field.value=data[field.name];if(field._editor)field._editor.innerHTML=richHtml(data[field.name])}for(const field of form.querySelectorAll('[data-image-upload]')){const img=$('.upload-preview',field.parentElement),url=data[field.dataset.imageUpload];if(img&&url){img.src=url;img.hidden=false}}form.dataset.editId=data.id;const submit=$('button[type="submit"]',form);if(submit){submit.dataset.originalText||=submit.innerHTML;submit.innerHTML='Simpan perubahan <span>→</span>'}form.scrollIntoView({behavior:'smooth',block:'center'});previewFormDraft(form);return}const imageEdit=e.target.closest('[data-edit-product-image]');if(imageEdit){const {data,error}=await client.from('products').select('*').eq('id',imageEdit.dataset.editProductImage).single();const form=$('#product-form');if(error||!data||!form)return alert('Foto produk tidak dapat dibuka untuk diedit.');for(const field of form.elements)if(field.name&&data[field.name]!=null){field.value=data[field.name];if(field._editor)field._editor.innerHTML=richHtml(data[field.name])}form.dataset.editId=data.id;const input=form.elements.image,preview=input&&$('.upload-preview',input.parentElement);if(preview){preview.src=data.image;preview.hidden=!data.image;preview.title='Klik untuk crop, putar, atau ubah ukuran'}const submit=$('button[type=submit]',form);if(submit){submit.dataset.originalText||=submit.innerHTML;submit.innerHTML='Simpan perubahan <span>→</span>'}form.scrollIntoView({behavior:'smooth',block:'center'});if(preview&&!preview.hidden)await editStoredImage(preview);else form.scrollIntoView({behavior:'smooth',block:'center'});return}const b=e.target.closest('[data-delete]');if(!b||!confirm('Hapus item ini dari website?'))return;const {error}=await client.from(b.dataset.delete).delete().eq('id',b.dataset.id);if(error)alert('Data tidak berhasil dihapus.');else{await renderAdmin();await renderPublic();markPreviewSaved('Entri dihapus dari website.')}});
}})}
