// A short branded loading veil prevents partially styled pages from flashing.
function finishLoading(){document.body.classList.add('is-ready');setTimeout(()=>$('.site-loader')?.remove(),550)}
if(document.readyState==='complete')finishLoading();else window.addEventListener('load',finishLoading,{once:true});
setTimeout(finishLoading,1800);
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});$$('body:not(.admin-body) main>section').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
